    if not o.rstrip().endswith(re.search(r'FINAL SCORE: \d+',o).group(0) if re.search(r'FINAL SCORE: \d+',o) else 'XX'): issues.append('tail')
    if issues: print(t['rating_id'],issues,o)
print('done')
